freeze.source:
def STEP(view, state):
    task = view['task_content']
    if state.get('done'):
        action = {'kind': 'stop', 'target': task['task_id'],
                  'inputs': {'reason': 'candidate complete'},
                  'evidence_refs': [], 'requested_resources': {}}
    else:
        action = {'kind': 'construct_method', 'target': task['task_id'],
                  'inputs': {'max_queries': 4}, 'evidence_refs': [],
                  'requested_resources': {'queries': 4}}
    return {'action': action, 'state': {'done': True}}

